import{_ as e,o,c as r,ag as a}from"./chunks/framework.CZxGLIO_.js";const l=JSON.parse('{"title":"GooseForum","description":"GooseForum 安装、使用和维护指南。","frontmatter":{"title":"GooseForum","description":"GooseForum 安装、使用和维护指南。"},"headers":[],"relativePath":"docs/gooseforum/index.md","filePath":"docs/gooseforum/index.md"}'),d={name:"docs/gooseforum/index.md"};function s(n,t,i,m,c,f){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="gooseforum" tabindex="-1">GooseForum <a class="header-anchor" href="#gooseforum" aria-label="Permalink to &quot;GooseForum&quot;">​</a></h1><p>GooseForum 是基于 Go 与 React 19 的社区平台，提供 Markdown 主题、回复、分类、通知和后台管理。默认使用 SQLite，可选 MySQL、PostgreSQL 与 S3 存储，生产前端资源嵌入单个可执行文件。</p><p>本文档于 2026-11-15 对照 <strong>v0.2.122</strong>、提交 <code>3044207</code> 核实，按已实现功能编写；systemd 等部署文件属于推荐操作示例。</p><h2 id="阅读顺序" tabindex="-1">阅读顺序 <a class="header-anchor" href="#阅读顺序" aria-label="Permalink to &quot;阅读顺序&quot;">​</a></h2><p>新站点建议按「安装 → 后台初始化 → 账号安全 → 生产部署」阅读。已有站点先核对配置，升级前备份并验证恢复；遇到具体异常再查故障排查。</p><table tabindex="0"><thead><tr><th>指南</th><th>内容</th></tr></thead><tbody><tr><td><a href="./installation/">安装与首次启动</a></td><td>发行包、源码构建、首次注册</td></tr><tr><td><a href="./administration/">后台初始化</a></td><td>邮件、分类、权限与第三方登录</td></tr><tr><td><a href="./configuration/">配置参考</a></td><td>TOML、数据库、存储与运行设置</td></tr><tr><td><a href="./security/">注册与账号安全</a></td><td>注册限额、可信代理、MFA 与恢复码</td></tr><tr><td><a href="./deployment/">生产部署</a></td><td>systemd、Caddy、HTTPS 与验证</td></tr><tr><td><a href="./maintenance/">备份、升级与恢复</a></td><td>备份范围、迁移、恢复演练与回退</td></tr><tr><td><a href="./troubleshooting/">故障排查</a></td><td>启动、邮件、附件、账号与更新问题</td></tr></tbody></table><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/README_ZH.md" target="_blank" rel="noreferrer">源码</a>。</p>',8)])])}const u=e(d,[["render",s]]);export{l as __pageData,u as default};
